function gameTime(){return clockText(gameDate());}

function toast(text){if(!S.assisted){text=immersiveMessage(text);if(!text)return;}$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4300);}
