function save(){if(S.mode==='intro')return;try{localStorage.setItem('santa-cruz-skiff-v1',JSON.stringify({...S,fishState:'idle',fish:null,anchor:S.anchor,elapsed:Math.round(S.elapsed),waypoint:null,autoWalk:false}));}catch{} }
let saved=null;try{saved=JSON.parse(localStorage.getItem('santa-cruz-skiff-v1')||'null');}catch{}if(saved?.version===1||saved?.version===2)$('#resume-btn').hidden=false;
function setPhase(phase){if(S.phase!==phase){S.phase=phase;updateUI();}}
function start(resume=false){if(S.mode!=='intro')return;resetTripClock();audio.init();if(resume&&saved){const migration=saved.version!==2;Object.assign(S,saved,{version:2,harborRevision:saved.harborRevision||0,profile:createProfile(saved.profile),fishState:'idle',fish:null,waypoint:null,autoWalk:false,paused:false,standing:false,swim:null,engine:false,throttle:0,speed:0});S.packed=Array.isArray(saved.packed)?saved.packed:[];S.catches=(saved.catches||[]).map((f,i)=>normalizeFishIdentity({...f,catchId:f.catchId||'legacy-'+i}));if(migration||saved.mode==='swim'){S.mode='walk';S.phase='walk';S.playerX=HARBOR.spawnX;S.playerZ=HARBOR.spawnZ;S.boatX=HARBOR.boatX;S.boatZ=HARBOR.boatZ;S.moored=true;S.launchStage='stored';}if(['lowering','raising','attaching'].includes(S.launchStage))S.launchStage='afloat';S.launchStage ||= 'afloat';migrateHarborSave(S);S.launchProgress=0;S.yaw=0;S.pitch=-.07;toast('航程已恢复，发动机保持关闭。');}else{S.mode='walk';journal('抵达 15 Municipal Wharf，开始今日航程。');toast('小屋就在前面约 8 米。整理装备、请求吊艇，然后出海。');}$('#intro').hidden=true;$('#location-card').hidden=true;$('#objectives').hidden=false;$('#toolbar').hidden=false;$('#nav-card').hidden=false;$('#reticle').hidden=false;$('#touch-controls').hidden=!touch.enabled;document.body.classList.add('playing');updateGearVisuals();updateUI();}

function updateGearVisuals(){world.gearObjects.forEach(o=>o.visible=!S.loaded);const gear=boat.userData.gear;if(gear){if(gear instanceof THREE.Object3D)gear.visible=S.loaded;else Object.values(gear).forEach(o=>{if(o instanceof THREE.Object3D)o.visible=S.loaded;});}if(boat.userData.cooler)boat.userData.cooler.visible=S.loaded&&S.packed.some(g=>g==='cooler'||g==='cooler_large');if(boat.userData.bucket)boat.userData.bucket.visible=S.loaded&&S.packed.includes('bait');if(boat.userData.net)boat.userData.net.visible=S.loaded&&S.packed.includes('net');}
function openModal(type,html){if(document.pointerLockElement)document.exitPointerLock();if(!S.paused)returnFocus=document.activeElement;modalType=type;S.paused=true;resetInput();document.body.classList.add('touch-paused');$('#modal-content').innerHTML=html;$('#modal-layer').hidden=false;$('#close-modal').focus();}
function closeModal(){if(modalType==='catch'&&S.fish){resolveCatch(false);return;}$('#modal-layer').hidden=true;S.paused=false;document.body.classList.remove('touch-paused');modalType='';returnFocus?.focus?.();returnFocus=null;}
const commerce=createCommerce({state:S,openModal,closeModal,toast,save,staffName:'码头值班员 · 模拟角色',launchBoat,onPacked:()=>{setPhase('board');S.loaded=false;updateGearVisuals();if(S.launchStage==='stored')launchBoat();else toast('装备准备好了。沿台阶到登船平台登船。');}});
function launchBoat(){if(S.mode!=='walk')return;if(S.launchStage==='afloat'){if(!S.moored){toast('先把木艇系回登船平台，再回收。');return;}S.launchStage='attaching';S.launchProgress=0;toast('空艇已经系妥。先下放吊钩连接吊索，再回收木艇。');journal('离船后，工作人员用吊臂回收空艇。');return;}if(S.launchStage!=='stored')return;S.launchStage='lowering';S.launchProgress=0;setPhase('board');journal('工作人员操作吊臂，下放空艇；待吊索卸载后登船。');toast('吊臂正在缓慢下放空艇。可以走到台阶旁观察。');}
function updateHoist(dt){if(!['lowering','raising','attaching'].includes(S.launchStage))return;S.launchProgress=Math.min(1,S.launchProgress+dt/(S.launchStage==='attaching'?6:24));if(S.launchProgress===1){if(S.launchStage==='attaching'){S.launchStage='raising';S.launchProgress=0;return;}S.launchStage=S.launchStage==='lowering'?'afloat':'stored';S.launchProgress=0;toast(S.launchStage==='afloat'?'空艇已下水，吊索已松开。可以登船。':'木艇已吊回，等待下次出航。');save();}}
function toggleStand(){if(S.mode!=='boat')return;if(S.moored&&S.launchStage!=='afloat')return;if(S.fishState!=='idle'){toast('先收回鱼线再在船内移动。');return;}resetInput();S.standing=!S.standing;S.deckX=-.35;S.deckZ=1.72;S.view='first';S.waypoint=null;S.throttle=0;S.engine=false;toast(S.standing?'站起后，摇杆在船内行走。走出舷边会落水。':'已回到驾驶座，可以操舵。');}
function enterWater(x,z,height){if(S.mode==='swim')return;resetInput();if(S.fishState!=='idle')retrieve();S.autoWalk=false;walkRoute=[];S.standing=false;S.waypoint=null;if(S.lanyard){S.engine=false;S.throttle=0;}S.swim=newImmersion(x,z,height,S.pfd);if(S.mode==='boat')S.yaw+=S.heading;S.mode='swim';S.view='first';audio.splash();journal(`落水：${S.pfd?'救生衣提供浮力':'未穿救生衣'}，${S.lanyard?'熄火绳切断发动机':'发动机未连接熄火绳'}。`);toast('落水！先稳定呼吸、漂浮休息，再靠近船尾梯。背包里可呼叫免费游戏救援。');}
function requestRescue(){closeModal();resetInput();S.waypoint=null;S.autoWalk=false;walkRoute=[];S.launchProgress=0;S.loaded=false;S.heading=0;updateGearVisuals();if(S.fishState!=='idle')retrieve();S.engine=false;S.throttle=0;S.speed=0;S.anchor=false;S.swim=null;S.standing=false;S.mode='walk';S.playerX=HARBOR.spawnX;S.playerZ=HARBOR.spawnZ;S.boatX=HARBOR.boatX;S.boatZ=HARBOR.boatZ;S.moored=true;S.launchStage='afloat';S.phase='walk';S.yaw=0;S.pitch=0;journal('使用免费游戏救援返回码头（跳过现实救援过程）。');toast('你和木艇已返回码头。此快捷救援为游戏辅助。');save();}
